// The bridge POSTs a flat JSON object. n8n's webhook node nests the
// request body under .body, so unwrap it (and tolerate a flat payload).
const a = $input.item.json.body || $input.item.json;
const level = Number(a.rule_level || 0);
const tier = level >= 13 ? 'CRITICAL' : level >= 10 ? 'HIGH' : level >= 7 ? 'MEDIUM' : 'LOW';
const mitre = Array.isArray(a.rule_mitre_ids) && a.rule_mitre_ids.length ? a.rule_mitre_ids.join(', ') : 'n/a';
const subject = `[Wazuh ${tier} L${level}] ${a.rule_description || 'Alert'} (${a.agent_name || 'unknown agent'})`.slice(0, 200);
const body = [
  `Severity : ${tier} (Wazuh level ${level})`,
  `Rule     : ${a.rule_id || 'n/a'} - ${a.rule_description || 'n/a'}`,
  `Agent    : ${a.agent_name || 'unknown'} (id ${a.agent_id || 'n/a'}, ${a.agent_ip || 'n/a'})`,
  `Source IP: ${a.src_ip || 'n/a'}`,
  `MITRE    : ${mitre}`,
  `Time     : ${a.timestamp || 'n/a'}`,
  '',
  'Full log:',
  String(a.full_log || '').slice(0, 1500),
  '',
  '-- sent by the SOC lab n8n workflow'
].join('\n');
return { json: { subject, body } };
